  Lemma has_instN : forall f, has instN f ->
    has A f \/ f = FCT p 8 m \/ f = FCT (p + 8) 1 in_aib \/
    (exists j, (j < Z.to_nat cnt)%nat /\ (f = FCT (slot_start in_mt (Z.of_nat j) - 4) 1 0 \/ f = FCT (slot_end in_mt (Z.of_nat j)) 1 0)) \/
